"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[38980],{64085:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TurretGuiController","desc":"Drives the authored, generic `StarterGui.TurretGui` gunner HUD for any\\nturret. It holds nothing turret-specific: it shows while\\n`Signals.OnTurretMounted` carries a Model and reads only that model\'s\\nattributes:\\n\\n- `DisplayName` (string; fallback `model.Name:upper()`)\\n- `Ammo`, `MagazineSize` (no `MagazineSize` hides the count row, the bar\\n  and the `R RELOAD` hint part)\\n- `Reloading`, `ReloadEndsAt` (server clock, `workspace:GetServerTimeNow()`),\\n  `ReloadTime`\\n\\n```\\nTurretGui (ScreenGui, IgnoreGuiInset)\\n\u251c\u2500\u2500 Crosshair (UIScale) { Up, Down, Left, Right, Dot }\\n\u251c\u2500\u2500 AmmoPanel (UIScale) { Name, NumRow { Count, Max }, State, Bar { Fill } }\\n\u251c\u2500\u2500 Hint (UIScale) { LeaveHint, Sep1, ReloadHint, Sep2, FireHint }\\n\u2514\u2500\u2500 FireButton (UIScale)\\n```\\n\\nThe crosshair is the exact screen centre the gunner\'s camera-centre ray\\nuses (`ViewportSize / 2`), hence `IgnoreGuiInset = true`. The key hint is\\ndesktop only and the FIRE button touch only (`UserInputService.TouchEnabled`);\\nthe button fires `Signals.TurretTrigger(true/false)`. The per-turret\\nattribute connections and the bar\'s `RenderStepped` live in a `Janitor`\\nthat is cleaned on every `OnTurretMounted` change.","realm":["Client"],"source":{"line":32,"path":"src/StarterPlayer/StarterPlayerScripts/TurretGuiController.client.luau"}}')}}]);